insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('6c7ced7a-69ce-4dd1-89a8-26d748bc2849', 'situacion', 'TINTÍN S2 · Pregunta 41', 'ctx-sit', '<p>Un estudiante une con segmentos cuatro lugares de un parque y afirma que forman un cuadrado.</p><figure class="ctx-fig"><img src="img/figuras/mat/ti2-q41-parque.webp" alt="Cuadrilátero con cuatro ángulos rectos; lados horizontales más largos que los verticales." loading="lazy"></figure>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('bb4101e3-46aa-4959-a340-4a77c68a5299', 'situacion', 'TINTÍN S2 · Pregunta 42', 'ctx-sit', '<p>Dos procesos de filtrado dejan F(x) = x − 8 y G(x) = x/2 partes por millón de cloro. La cantidad inicial es x = 20.</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('4ba72859-65bb-41a8-b2ed-7d6062bf8089', 'situacion', 'TINTÍN S2 · Pregunta 43', 'ctx-sit', '<p>El arriendo de un terreno rectangular se calcula multiplicando su área por $200.000 y añadiendo $100.000 por cada metro de frente. El terreno tiene 4 m de frente y 6 m de profundidad.</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('a7275111-cf3e-42ac-bc03-eb3c1a7d2080', 'situacion', 'TINTÍN S2 · Pregunta 44', 'ctx-sit', '<p>La gráfica distribuye los hogares de una ciudad por estrato.</p><figure class="ctx-fig"><img src="img/figuras/mat/ti2-q44-estratos.webp" alt="Estrato 1: 8 %, equivalente a 20.000 hogares; estrato 3: 34 %; estrato 4: 25 %; estrato 2 ocupa el resto." loading="lazy"></figure>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('8fdc5ad9-49f0-4309-8a07-223e88d4ee1a', 'situacion', 'TINTÍN S2 · Pregunta 45', 'ctx-sit', '<p>Un director elige una pareja entre Elisa, Diana y Alejandra. Cuenta tres opciones para la primera estudiante, dos para la segunda y multiplica 3×2 = 6 parejas.</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('ef19373c-2499-457a-86ef-51548ac2f3c8', 'situacion', 'TINTÍN S2 · Pregunta 46', 'ctx-sit', '<p>Para localizar una altura central se ordenan las mediciones, se cuenta n, se calcula (n + 1)/2 y, si da un entero, se toma la altura en esa posición.</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('9d274a70-5df1-417c-8456-53eafac22de6', 'situacion', 'TINTÍN S2 · Pregunta 47', 'ctx-sit', '<p>Un panadero prepara 75 galletas con 6 g de harina cada una y vende 65. Calcula: 1. 75×6. 2. 1 − 65/75. 3. Multiplica ambos resultados para obtener la harina correspondiente a las galletas sin vender.</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('58167dd1-5755-4cac-a0c1-bc2b47ffa3b8', 'situacion', 'TINTÍN S2 · Pregunta 48', 'ctx-sit', '<p>Un algoritmo toma un número positivo, calcula su raíz cuadrada, multiplica esa raíz por dos y eleva al cuadrado el resultado.</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('efaf9b53-d60c-4791-aed7-1c4484cb8a70', 'situacion', 'TINTÍN S2 · Pregunta 49', 'ctx-sit', '<p>Se registran temperaturas a las 12 m., 3 p. m., 6 p. m. y 9 p. m. en tres ciudades.</p><figure class="ctx-fig"><img src="img/figuras/mat/ti2-q49-temperaturas.webp" alt="Ciudad 1 desciende aproximadamente de 29,5 a 24,5 °C; ciudad 2 sube de 28,5 a 30,5 y luego baja a 20; ciudad 3 desciende de 23,5 a 16." loading="lazy"></figure>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('47fb790f-9d77-47e9-a482-2bc51577a32c', 'situacion', 'TINTÍN S2 · Pregunta 50', 'ctx-sit', '<p>Una vela cúbica de lado 2 cm lleva una cinta alrededor que cuesta x pesos. Al hacer otra de lado 4 cm, se necesita ocho veces más cera, pero se supone incorrectamente que la cinta costará 8x.</p><figure class="ctx-fig"><img src="img/figuras/mat/ti2-q50-vela.webp" alt="Vela cúbica con una cinta horizontal que rodea las cuatro caras laterales." loading="lazy"></figure>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('31543243-bbb0-4643-a691-179eadb66600', 'situacion', 'TINTÍN S2 · Pregunta 51', 'ctx-sit', '<p>Tratar una fotografía cuesta un punto por cm² de área, más un punto por cm de perímetro, más tres puntos por cm de su lado mayor. La fotografía mide 8 cm por 12 cm.</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('1cf58be0-1113-4546-ad2e-0781eef82053', 'situacion', 'TINTÍN S2 · Pregunta 52', 'ctx-sit', '<p>En un torneo se otorgan 100 puntos por victoria. El procedimiento para la puntuación máxima consiste en restar uno a la cantidad de equipos del grupo, tomar ese resultado como número de partidos del campeón y multiplicarlo por 100.</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('e868cc14-d675-49dc-a8f2-4c261a062329', 'situacion', 'TINTÍN S2 · Pregunta 53', 'ctx-sit', '<p>Se guardan bolas sólidas de radio 3 cm en un envase cilíndrico de radio 3,1 cm y altura 20 cm. Se verifica el diámetro y se divide la altura del envase entre el diámetro de una bola.</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('23c0a5a4-626f-4149-8ab6-959e01ddc54b', 'situacion', 'TINTÍN S2 · Pregunta 54', 'ctx-sit', '<p>Unos pescadores quieren elegir el día con pocos visitantes y poca probabilidad de lluvia para ir al lago.</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('8127c3e4-79f4-46eb-8508-2ee9ce485437', 'situacion', 'TINTÍN S2 · Pregunta 55', 'ctx-sit', '<p>La gráfica registra las ventas de cuatro productos durante enero, febrero, marzo y abril.</p><figure class="ctx-fig"><img src="img/figuras/mat/ti2-q55-ventas.webp" alt="Agua, gaseosas, cervezas y jugos; las gaseosas tienen la barra más alta en cada mes." loading="lazy"></figure>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('64f21a6b-759f-4b5f-8711-2e8d6aa9ce7a', 'situacion', 'TINTÍN S2 · Pregunta 56', 'ctx-sit', '<p>Un tiquete Madrid-Florida cuesta 500 euros. Al comprarlo, un euro equivale a 1,2 dólares.</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('81b9772b-c084-4e9d-b6df-3eedfd75f089', 'situacion', 'TINTÍN S2 · Pregunta 57', 'ctx-sit', '<p>Una inversión rinde el 10 % por trimestre. Al finalizar, la empresa cobra el 25 % del rendimiento. Se calcula el rendimiento, la comisión y se resta esta del rendimiento.</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('e33c08ee-388a-43fc-8fea-27683e3057ec', 'situacion', 'TINTÍN S2 · Pregunta 58', 'ctx-sit', '<p>El ejercicio define el centro de masa como el promedio de las coordenadas de los vértices. En el ejemplo triangular P(0,2), Q(2,3), R(4,−1), se obtiene M(2,4/3).</p><figure class="ctx-fig"><img src="img/figuras/mat/ti2-q58-ejemplo.webp" alt="Triángulo PQR con su centro M." loading="lazy"></figure><p>El cuadrilátero tiene vértices E(1,0), F(−1,5), G(4,6) y H(8,−1).</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('896bfab5-2010-434a-b641-5933a868df74', 'situacion', 'TINTÍN S2 · Pregunta 59', 'ctx-sit', '<p>Se quiere calcular el volumen de agua que llena el interior del cilindro. Se conocen el radio interno de 1 m y el grosor de 0,5 m.</p><figure class="ctx-fig"><img src="img/figuras/mat/ti2-q59-cilindro.webp" alt="Cilindro hueco con radio interno 1 m, grosor 0,5 m y altura sin valor numérico." loading="lazy"></figure>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('5edeadec-82c9-402b-b98e-97b671bf6965', 'situacion', 'TINTÍN S2 · Pregunta 60', 'ctx-sit', '<p>Una aplicación grafica las calorías registradas para Mónica y Julio al trotar durante 30 minutos.</p><figure class="ctx-fig"><img src="img/figuras/mat/ti2-q60-calorias.webp" alt="Mónica registra 10, 20, 30, 40, 50 y 60 calorías a los 5, 10, 15, 20, 25 y 30 minutos. Los puntos de Julio no siguen una recta y descienden en algunos intervalos." loading="lazy"></figure>');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
