insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('c46b94d8-b96c-4b3d-abcf-0b3a77bafe2b', 1, 'Cuatro ángulos rectos garantizan un rectángulo. Para ser cuadrado también deben ser iguales los cuatro lados, condición que el dibujo no cumple.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
