insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'fdfcb7f6-8b45-4225-b222-76eacef38ae4', 'mat',
  (select id from public.temas where materia = 'mat' and codigo = 'tablas-y-probabilidad'),
  (select id from public.lotes where codigo = '2026-B'),
  '8fdc5ad9-49f0-4309-8a07-223e88d4ee1a', 'Tablas y probabilidad',
  '¿Por qué es incorrecto el resultado?',
  array['Las cantidades deben sumarse, no multiplicarse.', 'Se incluye una pareja formada dos veces por la misma estudiante.', 'Se cuenta dos veces cada pareja, como Elisa-Diana y Diana-Elisa.', 'Hay que multiplicar también por las opciones de los estudiantes restantes.'],
