insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('fdfcb7f6-8b45-4225-b222-76eacef38ae4', 2, 'La pareja no tiene orden. Los seis resultados ordenados agrupan solo tres parejas distintas: Elisa-Diana, Elisa-Alejandra y Diana-Alejandra. Cada una aparece dos veces.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '5f4a5f9f-93a5-4f8e-8623-38b24bc49c78', 'mat',
  (select id from public.temas where materia = 'mat' and codigo = 'estadistica-descriptiva'),
  (select id from public.lotes where codigo = '2026-B'),
  'ef19373c-2499-457a-86ef-51548ac2f3c8', 'Estadística descriptiva',
  '¿Qué tabla permite obtener una posición entera y una altura específica?',
  array['<figure class="ctx-fig"><img src="img/figuras/mat/ti2-q46-a.webp" alt="Cuatro alturas exactas: 25, 26, 27 y 28 cm." loading="lazy"></figure>', '<figure class="ctx-fig"><img src="img/figuras/mat/ti2-q46-b.webp" alt="Cinco alturas exactas: 27, 25, 29, 30 y 22 cm." loading="lazy"></figure>', '<figure class="ctx-fig"><img src="img/figuras/mat/ti2-q46-c.webp" alt="Cuatro alturas agrupadas: 11–15, 16–20, 21–25 y 26 o más." loading="lazy"></figure>', '<figure class="ctx-fig"><img src="img/figuras/mat/ti2-q46-d.webp" alt="Cinco intervalos de altura: 10–14, 15–19, 20–24, 25–29 y 30 o más." loading="lazy"></figure>'],
  'Necesitas una cantidad impar de datos y mediciones individuales, no solo intervalos.', 'publicada', 'modelo', 'c2d15264f2f03d51dc1f855ed07f1c30', 'alta';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('5f4a5f9f-93a5-4f8e-8623-38b24bc49c78', 1, 'Cinco mediciones exactas dan la posición (5 + 1)/2 = 3. Ordenadas son 22, 25, 27, 29 y 30, así que la altura central es 27 cm. Los intervalos no identifican una altura exacta.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '24612713-001c-4a2c-90ee-2616a526ed90', 'mat',
  (select id from public.temas where materia = 'mat' and codigo = 'proporcionalidad'),
