insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('24612713-001c-4a2c-90ee-2616a526ed90', 0, 'El paso 1 da 450 g, el paso 2 da 10/75 y el resultado final es 60 g. Es entero, mayor que 10 y que 10/75, pero menor que 450.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '26442297-b67a-4469-816e-bb9aa0ea1db8', 'mat',
