insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('26442297-b67a-4469-816e-bb9aa0ea1db8', 0, 'La secuencia es 9 → 3 → 6 → 36. En general, (2√x)² = 4x para x positivo.');

