insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('2877ad5a-1638-479f-959d-9cbcd12bbb4c', 2, 'La cinta depende del perímetro horizontal: pasa de 4×2 a 4×4 cm, el doble. La cera depende del volumen y por eso aumenta con el cubo del factor de escala.');

