insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('078a69fa-56e9-45bb-8251-1e652e8eb775', 3, 'Área: 8×12 = 96. Perímetro: 2(8 + 12) = 40. Cargo por lado mayor: 3×12 = 36. Total: 96 + 40 + 36 = 172 puntos.');

