  '1cf58be0-1113-4546-ad2e-0781eef82053', 'Ecuaciones en contexto',
  'Siguiendo ese procedimiento con un grupo de 12 equipos, ¿cuál es la puntuación máxima?',
  array['1.100 puntos.', '1.200 puntos.', '1.600 puntos.', '2.800 puntos.'],
  'Aplica el procedimiento dado sin contar un partido contra el propio equipo.', 'publicada', 'modelo', 'f2248feba025903a5307156dd6bde1f2', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('356cc076-ef88-4ef2-91b3-fb8d3d0c3012', 0, 'Se calculan 12 − 1 = 11 partidos y luego 11×100 = 1.100 puntos. Es el resultado del procedimiento indicado para enfrentar una vez a los otros equipos.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
