insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('b9a863fc-4b53-4c27-bb49-7288f1a95ff3', 2, 'Cada bola tiene diámetro 6 cm y cabe en el diámetro de 6,2 cm del envase. En altura, 20/6 = 3,33; solo caben tres bolas completas en una columna.');

